import {FishingGame,FISH} from './fishing-engine.js';
import {loadWords} from './word-store.js';
import {readWords} from './vocab.js';
import {partyFX} from './party-fx.js';
import {bindGameLifecycle} from './game-lifecycle.js';
const $=id=>document.getElementById(id),sections=['intro','quiz','fight','reveal','result'];
let game=null,previous=0,pointer=null,muted=true,audio=null,book={};
try{const b=JSON.parse(localStorage.getItem('party-fish-book-v1')||'{}');if(b&&typeof b==='object')book=b;}catch{}
function tone(win=false){if(muted)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();[523,659,784,...(win?[1047,1319]:[])].forEach((hz,i)=>{const o=audio.createOscillator(),v=audio.createGain(),t=audio.currentTime+i*.09;o.type='triangle';o.frequency.value=hz;v.gain.setValueAtTime(0,t);v.gain.linearRampToValueAtTime(.09,t+.015);v.gain.exponentialRampToValueAtTime(.001,t+.22);o.connect(v);v.connect(audio.destination);o.start(t);o.stop(t+.23);});}catch{}}
$('sound').onclick=()=>{muted=!muted;$('sound').textContent=muted?'音 OFF':'音 ON';$('sound').setAttribute('aria-pressed',String(!muted));if(!muted)tone();};
function show(id){for(const s of sections)$(s).hidden=s!==id;}
function collection(){const list=$('collection');list.replaceChildren();let n=0;for(const f of FISH){const size=Number(book[f.name]);const p=document.createElement('p'),name=document.createElement('strong');name.textContent=(size?'🐠 ':'🔒 ')+(size?f.name:'まだ見ぬ魚');p.append(name,document.createTextNode(size?`最高 ${size} cm`:'釣って図鑑に登録！'));list.append(p);if(size)n++;}$('bookCount').textContent=n+' / 5';}
function clearInput(){pointer=null;game?.hold(false);$('reel').textContent='長押しで巻く！';}
function pause(value){if(!game||game.phase==='done')return;clearInput();game.pause(value);$('pauseScreen').hidden=!value;if(value){partyFX.clear();$('resume').focus();}else if(game.phase==='reel')$('reel').focus();}
bindGameLifecycle(window,document,{clearInput,pause});$('pause').onclick=()=>pause(true);$('resume').onclick=()=>pause(false);
function begin(){const pack=readWords(loadWords());try{if(pack.errors.length)throw Error(pack.errors[0]);game=new FishingGame(pack.entries);}catch(e){$('error').textContent=e.message;return;}clearInput();$('pauseScreen').hidden=true;partyFX.resetRewards();next();}
function next(){clearInput();if(!game.next())return;if(game.phase==='done'){show('result');$('resultTitle').textContent=game.catches.length+' / 5 匹 GET！';$('resultDetail').textContent=game.catches.length===5?'大漁パーフェクト！ 全ポイント制覇！':'釣れなかった魚に、もう一度挑もう！';$('review').replaceChildren();for(const p of game.misses){const el=document.createElement('p');el.textContent=p.word+' → '+p.meaning;$('review').append(el);}if(game.catches.length){partyFX.reward('clear','大漁ボーナス',game.catches.length*10);tone(true);}return;}
 show('quiz');$('ocean').className='ocean';$('fish').textContent=game.fish.icon;$('round').textContent=game.round+' / 5 投';$('location').textContent=['サンゴの入り江','南のラグーン','ぷかぷか沖','青い外海','黄金の秘境'][game.round-1];$('seaCaption').textContent=game.round===5?'伝説級の気配…！':'単語でえさを選ぼう';$('message').textContent='正しい意味を選ぶと、魚がヒット！';$('word').textContent=game.pair.word;$('choices').replaceChildren();game.options.forEach((p,i)=>{const b=document.createElement('button');b.textContent=p.meaning;b.onclick=()=>{if(game.phase!=='quiz'||game.paused)return;const ok=game.answer(i);if(ok){show('fight');$('ocean').className='ocean fighting';$('message').textContent='HIT！ 長押しで巻いて、暴れたら離そう';partyFX.burst('good','HIT！');tone();renderFight();}else reveal();};$('choices').append(b);});}
function reveal(){clearInput();show('reveal');const caught=game.phase==='caught';$('ocean').className='ocean'+(caught?' caught'+(game.round===5?' legendary':''):'');$('catchKicker').textContent=caught?(game.round===5?'LEGENDARY CATCH!':'FISH GET!'):'TRY AGAIN';$('catchTitle').textContent=caught?game.catch.name:'ざんねん…！';$('answerReview').textContent=game.pair.word+' → '+game.pair.meaning;$('next').textContent=game.round===5?'釣果を発表！':'次のポイントへ！';if(caught){const f=game.catch,newRecord=f.size>(Number(book[f.name])||0);book[f.name]=Math.max(f.size,Number(book[f.name])||0);let saved=true;try{localStorage.setItem('party-fish-book-v1',JSON.stringify(book));}catch{saved=false;}collection();$('catchDetail').textContent=`${f.size} cm ・ ランク ${f.grade} ・ ★＋${f.points}`+(newRecord?' ／ NEW RECORD！':'')+(!saved?'（記録は今回のみ）':'');$('seaCaption').textContent=game.round===5?'伝説の大物、釣り上げた！':'大物 GET！';$('message').textContent=game.streak>1?game.streak+'連続キャッチ！':'ナイスフィッシング！';partyFX.reward('catch-'+game.round,'釣り上げた！',f.points,game.streak);partyFX.burst('win',newRecord?'新記録！ '+f.size+' cm':'FISH GET！');tone(true);}else{$('catchDetail').textContent=game.reason;$('seaCaption').textContent='次こそ釣り上げよう';$('message').textContent='正しい意味と、巻くタイミングをチェック！';partyFX.burst('miss','次の一投でリベンジ！');}}
function renderFight(){$('progress').value=game.progress;$('tension').value=game.tension;$('progressText').textContent=Math.floor(game.progress)+'%';$('tensionText').textContent=Math.floor(game.tension)+'%';$('remaining').textContent=Math.ceil(22-game.elapsed)+'秒';const warning=game.surge||game.tension>75;$('behavior').textContent=warning?'あばれてる！ 指を離そう':'今だ！ 長押しで巻こう';$('fight').classList.toggle('danger',warning);$('ocean').classList.toggle('surge',game.surge);$('seaCaption').textContent=warning?'ゆるめて！':'ぐいぐい巻こう！';}
const reel=$('reel');reel.addEventListener('pointerdown',e=>{if(!game||game.phase!=='reel'||game.paused||pointer!==null||e.button>0)return;e.preventDefault();pointer=e.pointerId;try{reel.setPointerCapture(pointer);}catch{}game.hold(true);reel.textContent='巻いてる！ 離すとゆるむ';});for(const event of ['pointerup','pointercancel','lostpointercapture'])reel.addEventListener(event,e=>{if(e.pointerId===pointer)clearInput();});reel.addEventListener('contextmenu',e=>e.preventDefault());window.addEventListener('keydown',e=>{if(e.code==='Space'&&game?.phase==='reel'&&!game.paused){e.preventDefault();game.hold(true);}});window.addEventListener('keyup',e=>{if(e.code==='Space')clearInput();});
function frame(now){const dt=previous?Math.min((now-previous)/1000,.1):0;previous=now;if(game?.phase==='reel'&&!game.paused){game.tick(dt);if(game.phase==='reel')renderFight();else reveal();}requestAnimationFrame(frame);}
$('start').onclick=begin;$('again').onclick=begin;$('next').onclick=next;collection();requestAnimationFrame(frame);
